    @responses.activate
    def test_create_hdfs_storage_value_error(self):
        """
        test_create_hdfs_storage_value_error()
        """
        # Set up mock
        url = preprocess_url('/v3/storage_hdfs_registrations')
        mock_response = '{"actions": ["actions"], "associated_catalog": {"base_path": "/abc/def", "catalog_name": "sampleCatalog", "catalog_tags": ["catalog_tags"], "catalog_type": "iceberg"}, "created_at": "1686120645", "created_by": "<username>@<domain>.com", "description": "HDFS description for storage", "display_name": "sample hdfs displayname", "id": "hdfs123", "managed_by": "customer", "state": "active", "tags": ["tags"], "type": "hdfs"}'
        responses.add(
            responses.POST,
            url,
            body=mock_response,
            content_type='application/json',
            status=201,
        )

        # Set up parameter values
        display_name = 'testString'
        type = 'testString'
        hms_thrift_uri = 'testString'
        hms_thrift_port = 1
        core_site = 'testString'
        hdfs_site = 'testString'
        kerberos = 'testString'
        catalog_name = 'testString'
        catalog_type = 'testString'

        # Pass in all but one required param and check for a ValueError
        req_param_dict = {
            "display_name": display_name,
            "type": type,
            "hms_thrift_uri": hms_thrift_uri,
            "hms_thrift_port": hms_thrift_port,
            "core_site": core_site,
            "hdfs_site": hdfs_site,
            "kerberos": kerberos,
            "catalog_name": catalog_name,
            "catalog_type": catalog_type,
        }
        for param in req_param_dict.keys():
            req_copy = {key: val if key is not param else None for (key, val) in req_param_dict.items()}
            with pytest.raises(ValueError):
                _service.create_hdfs_storage(**req_copy)

