class TestModel_AccessPolicies:
    """
    Test Class for AccessPolicies
    """

    def test_access_policies_serialization(self):
        """
        Test serialization/deserialization for AccessPolicies
        """

        # Construct dict forms of any model objects needed in order to build this model.

        metadata_model = {}  # Metadata
        metadata_model['created_at'] = '2025-08-05T12:34:56Z'
        metadata_model['created_by'] = 'creator'
        metadata_model['last_modified_at'] = '2025-08-05T12:34:56Z'
        metadata_model['last_modified_by'] = 'modifier'

        permission_model = {}  # Permission
        permission_model['action'] = 'can_administer'
        permission_model['permission_type'] = 'explicit'

        resource_details_model = {}  # ResourceDetails
        resource_details_model['id'] = 'presto01'
        resource_details_model['name'] = 'hive_data'
        resource_details_model['type'] = 'presto'

        subject_model = {}  # Subject
        subject_model['type'] = 'user'
        subject_model['value'] = 'user1'

        access_policy_model = {}  # AccessPolicy
        access_policy_model['metadata'] = metadata_model
        access_policy_model['permissions'] = [permission_model]
        access_policy_model['resource'] = resource_details_model
        access_policy_model['state'] = 'active'
        access_policy_model['subject'] = subject_model

        # Construct a json representation of a AccessPolicies model
        access_policies_model_json = {}
        access_policies_model_json['access_policies'] = [access_policy_model]
        access_policies_model_json['account_id'] = 'testString'
        access_policies_model_json['instance_id'] = 'testString'
        access_policies_model_json['limit'] = 20
        access_policies_model_json['offset'] = 2
        access_policies_model_json['total_count'] = 200

        # Construct a model instance of AccessPolicies by calling from_dict on the json representation
        access_policies_model = AccessPolicies.from_dict(access_policies_model_json)
        assert access_policies_model != False

        # Construct a model instance of AccessPolicies by calling from_dict on the json representation
        access_policies_model_dict = AccessPolicies.from_dict(access_policies_model_json).__dict__
        access_policies_model2 = AccessPolicies(**access_policies_model_dict)

        # Verify the model instances are equivalent
        assert access_policies_model == access_policies_model2

        # Convert model instance back to dict and verify no loss of data
        access_policies_model_json2 = access_policies_model.to_dict()
        assert access_policies_model_json2 == access_policies_model_json


